bool ExecutionContext::solveContinuous(parser::InputParser* parser,
                                       bool stopAtSetLogic,
                                       bool stopAtCheckSat)
{
  Command cmd;
  bool interrupted = false;
  bool status = true;
  while (status)
  {
    if (interrupted)
    {
      solver().getDriverOptions().out() << CommandInterrupted();
      d_executor->reset();
      break;
    }
    cmd = parser->nextCommand();
    if (cmd.isNull())
    {
      break;
    }
    Cmd* cc = cmd.d_cmd.get();
    if (stopAtCheckSat)
    {
      if (dynamic_cast<CheckSatCommand*>(cc) != nullptr)
      {
        d_hasReadCheckSat = true;
        break;
      }
    }
    status = d_executor->doCommand(&cmd);
    if (cc->interrupted() && status == 0)
    {
      interrupted = true;
      break;
    }
    if (dynamic_cast<QuitCommand*>(cc) != nullptr)
    {
      break;
    }
    if (stopAtSetLogic)
    {
      auto* slc = dynamic_cast<SetBenchmarkLogicCommand*>(cc);
      if (slc != nullptr)
      {
        d_logic = slc->getLogic();
        break;
      }
    }
  }
  return status;
}

bool PortfolioDriver::solve(std::unique_ptr<CommandExecutor>& executor)
{
  ExecutionContext ctx{executor.get()};
  Solver& solver = ctx.solver();
  bool use_portfolio = solver.getOption("use-portfolio") == "true";
  if (!use_portfolio)
  {
    return ctx.solveContinuous(d_parser, false);
  }

bool Cmd::ok() const
{
  // either we haven't run the command yet, or it ran successfully
  return d_commandStatus == nullptr
         || dynamic_cast<const CommandSuccess*>(d_commandStatus) != nullptr;
}

bool Cmd::fail() const
{
  return d_commandStatus != nullptr
         && dynamic_cast<const CommandFailure*>(d_commandStatus) != nullptr;
}

bool Cmd::interrupted() const
{
  return d_commandStatus != nullptr
         && dynamic_cast<const CommandInterrupted*>(d_commandStatus) != nullptr;
}

void Cmd::invoke(cvc5::Solver* solver,
                 parser::SymManager* sm,
                 std::ostream& out)
{
  invoke(solver, sm);
  if (!ok())
  {
    out << *d_commandStatus;
  }
  else
  {
    printResult(solver, out);
  }
  // always flush the output
  out << std::flush;
}

void Cmd::invokeAndPrintResult(cvc5::Solver* solver,
                               parser::SymManager* sm)
{
  invoke(solver, sm);
  // the output stream reference is retrieved here since it might change after
  // invoking a (set-option :out ...) command
  std::ostream &out = solver->getDriverOptions().out();
  if (!ok())
  {
    out << *d_commandStatus;
  }
  else
  {
    printResult(solver, out);
  }
  // always flush the output
  out << std::flush;
}

